<?php requireRole(['Administrator','Editor','Viewer','Guest']); require_once __DIR__.'/../app/layout.php';
$year=(int)($_GET['year']??date('Y'));$pdo=db();
$ppmp=(int)$pdo->query("SELECT COUNT(*) FROM ppmp_items WHERE fiscal_year=$year")->fetchColumn();$areas=(int)$pdo->query("SELECT COUNT(DISTINCT area_id) FROM ppmp_items WHERE fiscal_year=$year")->fetchColumn();$qty=(float)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM ppmp_items WHERE fiscal_year=$year")->fetchColumn();$abc=(float)$pdo->query("SELECT COALESCE(SUM(quantity*unit_price),0) FROM ppmp_items WHERE fiscal_year=$year")->fetchColumn();
$prCount=(int)$pdo->query("SELECT COUNT(*) FROM purchase_requests WHERE fiscal_year=$year AND status<>'Cancelled'")->fetchColumn();$poCount=(int)$pdo->query("SELECT COUNT(*) FROM purchase_orders o JOIN purchase_requests r ON r.id=o.pr_id WHERE r.fiscal_year=$year AND o.status<>'Cancelled'")->fetchColumn();
$recent=$pdo->prepare('SELECT p.*,a.name area,c.name category FROM ppmp_items p JOIN areas a ON a.id=p.area_id JOIN categories c ON c.id=p.category_id WHERE fiscal_year=? ORDER BY p.created_at DESC LIMIT 8');$recent->execute([$year]);pageStart('Dashboard');
?><div class="cards"><div class="card"><div class="label">PPMP Line Items</div><div class="metric"><?=number_format($ppmp)?></div><div class="hint">FY <?=$year?></div></div><div class="card"><div class="label">Participating Areas/Units</div><div class="metric"><?=number_format($areas)?></div><div class="hint">With submitted PPMP items</div></div><div class="card"><div class="label">Total Planned Quantity</div><div class="metric"><?=number_format($qty,2)?></div><div class="hint">Across all PPMPs</div></div><div class="card"><div class="label">Total Planned ABC</div><div class="metric">₱<?=number_format($abc,2)?></div><div class="hint">Quantity × unit price</div></div></div>
<div class="cards" style="margin-top:16px"><div class="card"><div class="label">Purchase Requests</div><div class="metric"><?=number_format($prCount)?></div><div class="hint">Non-cancelled FY <?=$year?></div></div><div class="card"><div class="label">Purchase Orders</div><div class="metric"><?=number_format($poCount)?></div><div class="hint">Non-cancelled FY <?=$year?></div></div></div>
<div class="grid"><div class="panel"><h2>Recent PPMP Entries</h2><div class="table-wrap"><table class="table"><tr><th>Item</th><th>Area/Unit</th><th>Category</th><th>Qty</th><th>ABC</th></tr><?php foreach($recent as $r):?><tr><td><?=e($r['item_name'])?></td><td><?=e($r['area'])?></td><td><?=e($r['category'])?></td><td><?=number_format($r['quantity'],2).' '.e($r['unit'])?></td><td>₱<?=number_format($r['quantity']*$r['unit_price'],2)?></td></tr><?php endforeach;?></table></div></div><div class="panel"><h2>Procurement Workflow</h2><p>1. Area/Unit prepares its PPMP.</p><p>2. Equivalent PPMP items are consolidated into the APP.</p><p>3. Authorized users create PRs from available PPMP quantities.</p><p>4. PR quantities automatically reduce remaining planned quantities.</p><p>5. Submitted/approved PRs can be converted into POs with supplier details.</p><a class="btn" href="app.php?year=<?=$year?>">View Consolidated APP</a></div></div><?php pageEnd();